class _FlowLimiter:
    """Stand-in for the server's flow limiters (light pacing)."""

    def __init__(self, interval=0.2):
        self._interval = interval
        self._last = 0.0
        self._lock = threading.Lock()

    def wait_slot(self):
        with self._lock:
            now = time.time()
            wait = self._interval - (now - self._last)
            if wait > 0:
                time.sleep(wait)
            self._last = time.time()


global_flow_limiter = _FlowLimiter()
replay_flow_limiter = _FlowLimiter()


