def form_urlencode_value (s :str )->str :
    out =[]
    for byte in s .encode ('utf-8'):
        ch =chr (byte )
        if ch .isascii ()and (ch .isalnum ()or ch in '*-._'):
            out .append (ch )
        elif byte ==32 :
            out .append ('+')
        else :
            out .append (f'%{byte :02X}')
    return ''.join (out )

