def _prefetch(tag, url, headers):
    try:
        text = fetch_abs_playlist(url)
        segs = [l.strip() for l in text.splitlines() if l.strip() and not l.startswith("#")]
        if not segs:
            _diag("pf", tag + " noseg")
            return
        h = dict(headers)
        h["Range"] = "bytes=0-187"
        req = urllib.request.Request(segs[0], headers=h)
        with _open_req(req, 8) as r:
            r.read(188)
        _diag("pf", "%s ok" % tag)
    except Exception as e:
        _diag("pf", "%s %s" % (tag, str(e)[:40]))


def _diag(kind, msg):
    _DIAG.append("%s:%s" % (kind, msg))
    while len(_DIAG) > 10:
        _DIAG.pop(0)


def _device_json_path():
    try:
        return os.path.join(os.path.dirname(os.path.abspath(__file__)), "ysp_device_state.json")
    except Exception:
        return os.path.join(tempfile.gettempdir(), "ysp_device_state.json")


class _Args(object):
    pass


def _get_engine():
    global _ENGINE
    if _ENGINE is None:
        with _ENGINE_LOCK:
            if _ENGINE is None:
                a = _Args()
                a.timeout = 10.0
                a.insecure_tls = False
                a.device_json = _device_json_path()
                a.cache_ttl = 60.0
                a.refresh_interval = 1.0
                a.control_step_jitter_min_ms = 0
                a.control_step_jitter_max_ms = 0
                a.session_ttl = 7200.0
                _ENGINE = _Engine(a)
    return _ENGINE


def _group_of(slug):
    return "央视" if (slug.startswith("cctv") or slug.startswith("cgtn")) else "卫视"


def _logo_url(ch):
    if _start_server():
        return "http://127.0.0.1:%d/logo/%s" % (_SRV["port"], ch[0])
    u = LOGO_MAP.get(ch[0])
    if u:
        return u
    return "https://live.fanmingming.com/tv/%s.png" % urllib.parse.quote(ch[1])


def _bk_resolve(ch, fresh=False):
    slug = ch[0]
    now = time.time()
    hit = _BK_CACHE.get(slug)
    if hit and not fresh and now - hit[0] < 300:
        return hit[1]
    urls = [u for u in bk_playurls(ch[2], ch[3], ch[4] or "fhd") if ".cctv." in u]
    if not urls:
        raise RuntimeError("BK 无可用线路")
    _diag("bkurl", "len=%d tail=%s" % (len(urls[0]), urls[0][-45:]))
    _BK_CACHE[slug] = (now, urls)
    return urls


def _upgrade_https(text):
    out = []
    for line in text.splitlines():
        ls = line.strip()
        if ls.startswith("http://"):
            line = "https://" + ls[7:]
        elif 'URI="http://' in line:
            line = line.replace('URI="http://', 'URI="https://')
        out.append(line)
    return "\n".join(out) + "\n"


def _absolutize(text, base):
    out = []
    for line in text.splitlines():
        ls = line.strip()
        if ls and not ls.startswith("#"):
            out.append(urllib.parse.urljoin(base, ls))
        elif 'URI="' in ls:
            out.append(re.sub(r'URI="([^"]+)"',
                              lambda m: 'URI="%s"' % urllib.parse.urljoin(base, m.group(1)), line))
        else:
            out.append(line)
    return "\n".join(out) + "\n"


def _rewrite_seg_proxy(text, token):
    out = []
    for line in text.splitlines():
        ls = line.strip()
        if ls and not ls.startswith("#"):
            out.append("proxy://do=seg&t=%s&u=%s" % (token, urllib.parse.quote(ls, safe="")))
        elif 'URI="' in ls:
            def _rep(m):
                return 'URI="proxy://do=seg&t=%s&u=%s"' % (token, urllib.parse.quote(m.group(1), safe=""))
            out.append(re.sub(r'URI="([^"]+)"', _rep, line))
        else:
            out.append(line)
    return "\n".join(out) + "\n"


def _norm_params(params):
    if isinstance(params, dict):
        out = {}
        for k, v in params.items():
            if isinstance(v, (list, tuple)):
                v = v[0] if v else ""
            out[str(k)] = v if isinstance(v, str) else (json.dumps(v) if isinstance(v, (dict, list)) else str(v))
        return out
    if isinstance(params, str):
        t = params.strip()
        if t.startswith("{"):
            try:
                return _norm_params(json.loads(t))
            except Exception:
                pass
        if t.startswith("proxy://"):
            t = t[len("proxy://"):]
        q = t.split("?", 1)[-1]
        return dict(urllib.parse.parse_qsl(q))
    return {}


def _proxy_params(params):
    p = _norm_params(params)
    if "do" not in p and isinstance(params, str) and "do=" in params:
        raw = params[len("proxy://"):] if params.startswith("proxy://") else params
        p.update(dict(urllib.parse.parse_qsl(raw.split("?", 1)[-1])))
    return p


def _media_url(master_url):
    try:
        req = urllib.request.Request(master_url, headers=dict(PLAY_HEADERS))
        with _open_req(req, 10) as r:
            text = r.read().decode("utf-8", "ignore")
            final = r.geturl()
        if "#EXT-X-STREAM-INF" in text:
            for line in text.splitlines():
                ls = line.strip()
                if ls and not ls.startswith("#"):
                    return urllib.parse.urljoin(final, ls)
        return final
    except Exception:
        return master_url



_SRV = {"port": None, "err": ""}
_TS_LOCK = threading.Lock()
_TS_PL_CACHE = {}
_TS_RL_UNTIL = [0.0]
_SEG_Q = {}
_SEG_CACHE = {}
_SEG_PL = {}
_POOL = {}
_POOL_LOCKS = {}
_POOL_LOCK = threading.Lock()
_POOL_UNVERIFIED = set()
_SEG_FAIL = {}
_BK_FAIL = {}
_SLUG_MAP = {c[0]: c for c in DEFAULT_CHANNELS}


def _seg_cache_put(url, data, ctype):
    if len(_SEG_CACHE) > 48:
        for _k, _v in sorted(_SEG_CACHE.items(), key=lambda kv: kv[1][2])[:16]:
            _SEG_CACHE.pop(_k, None)
    _SEG_CACHE[url] = (data, ctype, time.time())


def _fetch_seg_bytes(url, headers, timeout=10):
    req = urllib.request.Request(url, headers=headers)
    with _open_req(req, timeout) as r:
        data = r.read(16 * 1024 * 1024 + 1)
        ctype = r.headers.get("Content-Type") or "video/MP2T"
    if len(data) > 16 * 1024 * 1024:
        raise RuntimeError("segment too large")
    if not data:
        raise RuntimeError("empty segment")
    return data, ctype


def _prefetch_last(text):
    # Mirror the author's cold-start warm-up: pull the live-edge segment into
    # the cache while the player is still loading the playlist.
    try:
        _segs = [l.strip() for l in text.splitlines() if l.strip() and not l.startswith("#")]
        if not _segs:
            return
        _u = _segs[-1]
        if not _u.startswith("http") or _u in _SEG_CACHE:
            return

        def _go():
            try:
                status, hdrs, body, _f = _pool_fetch(_u, {"Range": "bytes=0-"}, timeout=8)
                if status in (200, 206) and body:
                    _seg_cache_put(_u, body, hdrs.get("content-type") or "video/MP2T")
                    _diag("warm", urllib.parse.urlparse(_u).hostname or "?")
            except Exception:
                pass

        threading.Thread(target=_go, daemon=True).start()
    except Exception:
        pass


def _host_lock(host):
    with _POOL_LOCK:
        lk = _POOL_LOCKS.get(host)
        if lk is None:
            lk = threading.Lock()
            _POOL_LOCKS[host] = lk
        return lk


def _pool_drop(host):
    with _POOL_LOCK:
        ent = _POOL.pop(host, None)
    if ent:
        try:
            ent.close()
        except Exception:
            pass


def _pool_fetch(url, headers, timeout=10):
    # One buffered GET over a per-host persistent connection. Playlist and
    # segment fetches for a CDN host share ONE TCP connection, so any
    # session the CDN binds to the playlist fetch (NAT egress, connection
    # state) also covers the segment fetches. Returns (status, headers, body, final_url).
    import http.client as _hcl
    import ssl as _ssl
    cur = url
    for _hop in range(4):
        parts = urllib.parse.urlsplit(cur)
        host = parts.hostname or ""
        port = parts.port or (443 if parts.scheme == "https" else 80)
        path = urllib.parse.urlunsplit(("", "", parts.path or "/", parts.query, ""))
        with _host_lock(host):
            with _POOL_LOCK:
                conn = _POOL.get(host)
            if conn is None:
                if parts.scheme == "https":
                    ctx = _ssl._create_unverified_context() if host in _POOL_UNVERIFIED else None
                    conn = _hcl.HTTPSConnection(host, port, timeout=timeout, context=ctx) if ctx else _hcl.HTTPSConnection(host, port, timeout=timeout)
                else:
                    conn = _hcl.HTTPConnection(host, port, timeout=timeout)
                with _POOL_LOCK:
                    _POOL[host] = conn
            try:
                conn.request("GET", path, headers=dict(headers))
                resp = conn.getresponse()
                body = resp.read()
                status = resp.status
                hdrs = {k.lower(): v for k, v in resp.getheaders()}
            except Exception as e:
                _pool_drop(host)
                if parts.scheme == "https" and host not in _POOL_UNVERIFIED and ("certificate" in str(e).lower() or "ssl" in str(e).lower()):
                    _POOL_UNVERIFIED.add(host)
                    continue
                raise
        if status in (301, 302, 303, 307, 308) and hdrs.get("location"):
            cur = urllib.parse.urljoin(cur, hdrs["location"])
            continue
        return status, hdrs, body, cur
    raise RuntimeError("too many redirects")


_PL_HEADERS = {"User-Agent": "qqlive", "Referer": "https://live.cctv.cn/",
               "Accept": "application/vnd.apple.mpegurl,application/json,*/*"}


def _fetch_playlist_pooled(url, depth=0):
    status, hdrs, body, final = _pool_fetch(url, _PL_HEADERS, timeout=10)
    if status != 200:
        raise urllib.error.HTTPError(url, status, "playlist HTTP %s" % status, {}, None)
    text = body.decode("utf-8", "replace")
    if depth < 2:
        lines = text.splitlines()
        for i, ln in enumerate(lines):
            if ln.strip().startswith("#EXT-X-STREAM-INF"):
                for j in range(i + 1, len(lines)):
                    s2 = lines[j].strip()
                    if s2 and not s2.startswith("#"):
                        return _fetch_playlist_pooled(urllib.parse.urljoin(final, s2), depth + 1)
                break
    return _absolutize(text, final), final


_FORCE_BK = {"cctv11", "cctv12", "cctv14", "cctv15", "cctv16", "cctv17",
             "cctvfyjc", "cctvdyjc", "cctvhjjc"}
_JCE_LIVE = {}
_JCE_PL_CACHE = {}
_JCE_LASTGOOD = {}
_JCE_GUID = [None]


def _jce_guid():
    if _JCE_GUID[0]:
        return _JCE_GUID[0]
    g = ""
    try:
        p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "ysp_jce_guid.txt")
        if os.path.exists(p):
            g = open(p).read().strip()
        if not g:
            g = str(GUID)
            with open(p, "w") as f:
                f.write(g)
    except Exception:
        g = str(GUID)
    _JCE_GUID[0] = g
    return g


def _jce_live_url(ch):
    # Flagship v20261124 design: live = a timeshift window [now-120, now+900]
    # resolved through JCE; one resolve serves ~13 min (soft 810s / hard 885s).
    slug = ch[0]
    now = time.time()
    ent = _JCE_LIVE.get(slug)
    if ent and now < ent[1]:
        return ent[0]
    if ent and now < ent[2] and time.time() < _TS_RL_UNTIL[0]:
        return ent[0]
    with _TS_LOCK:
        ent = _JCE_LIVE.get(slug)
        now = time.time()
        if ent and now < ent[1]:
            return ent[0]
        if time.time() < _TS_RL_UNTIL[0]:
            if ent:
                return ent[0]
            raise RuntimeError("jce cooling")
        try:
            ni = int(now)
            url = jce_timeshift_url(ch[3], ch[2], ni - 120, ni + 900, ch[4] or "fhd")
        except Exception as e:
            if "频繁" in str(e):
                _TS_RL_UNTIL[0] = time.time() + 90
            raise
        _JCE_LIVE[slug] = (url, now + 810, now + 885)
        _diag("jceurl", urllib.parse.urlparse(url).hostname or "?")
        return url


def _jce_live_playlist(ch):
    # Synthesize a live playlist from the JCE window playlist: last 15
    # segments, newest held back, segment URLs stay DIRECT (no relay),
    # exactly like the flagship gateway builds it.
    slug = ch[0]
    hit = _JCE_PL_CACHE.get(slug)
    if hit and time.time() - hit[1] < 4:
        return hit[0]
    try:
        url = _jce_live_url(ch)
    except Exception:
        if slug in _JCE_LASTGOOD:
            return _JCE_LASTGOOD[slug]
        raise
    headers = {"User-Agent": "qqlive", "UID": _jce_guid(),
               "Accept": "application/vnd.apple.mpegurl,application/x-mpegURL,*/*"}
    cands = [url]
    if "tlivecloud-playback-cdn" in url:
        cands.append(url.replace("tlivecloud-playback-cdn", "bktlivecloud-playback-cdn"))
    text = None
    final = url
    last = None
    for cand in cands:
        try:
            req = urllib.request.Request(cand, headers=headers)
            with _open_req(req, 8) as r:
                text = r.read().decode("utf-8", "replace")
                final = r.geturl() or cand
            if text and "#EXTM3U" in text:
                if cand != url:
                    ent = _JCE_LIVE.get(slug)
                    if ent:
                        _JCE_LIVE[slug] = (cand, ent[1], ent[2])
                break
            text = None
        except Exception as e:
            last = e
    if text is None:
        if slug in _JCE_LASTGOOD:
            return _JCE_LASTGOOD[slug]
        raise RuntimeError("jce playlist: %s" % str(last)[:60])
    segs = []
    dur = 0.0
    for ln in text.splitlines():
        s2 = ln.strip()
        if s2.startswith("#EXTINF:"):
            try:
                dur = float(s2[8:].split(",")[0])
            except Exception:
                dur = 0.0
        elif s2 and not s2.startswith("#"):
            segs.append((dur, urllib.parse.urljoin(final, s2)))
            dur = 0.0
    if not segs:
        if slug in _JCE_LASTGOOD:
            return _JCE_LASTGOOD[slug]
        raise RuntimeError("jce playlist empty")
    disp = segs[-15:]
    if len(disp) >= 4:
        disp = disp[:-1]
    target = 6
    for d2, _u in disp:
        target = max(target, int(d2 + 0.5))
    seq = len(segs) - len(disp)
    mseq = re.search(r"-(\d+)\.[A-Za-z0-9]+(?:\?|$)", disp[0][1]) if disp else None
    if mseq:
        # Segment filenames carry a per-channel counter; anchoring
        # MEDIA-SEQUENCE to it keeps sequence<->segment identity stable
        # across polls while the upstream window slides (the old
        # count-based sequence renumbered the same segments every poll,
        # which stalled the player on some channels).
        seq = int(mseq.group(1))
    out = ["#EXTM3U", "#EXT-X-VERSION:3", "#EXT-X-TARGETDURATION:%d" % target,
           "#EXT-X-MEDIA-SEQUENCE:%d" % seq]
    for d2, u2 in disp:
        out.append("#EXTINF:%.3f," % d2)
        out.append(u2)
    body = "\n".join(out) + "\n"
    _JCE_PL_CACHE[slug] = (body, time.time())
    _JCE_LASTGOOD[slug] = body
    return body


def _rewrite_seg_http(text, token):
    base = "http://127.0.0.1:%d/seg?t=%s&u=" % (_SRV["port"], token)
    out = []
    for line in text.splitlines():
        ls = line.strip()
        if ls and not ls.startswith("#"):
            out.append(base + urllib.parse.quote(ls, safe=""))
        elif 'URI="' in ls:
            def _rep(m):
                return 'URI="%s%s"' % (base, urllib.parse.quote(m.group(1), safe=""))
            out.append(re.sub(r'URI="([^"]+)"', _rep, line))
        else:
            out.append(line)
    return "\n".join(out) + "\n"


def _start_server():
    if _SRV["port"]:
        return _SRV["port"]
    if _SRV["err"]:
        return None
    try:
        import http.server as _hs

        class _H(_hs.BaseHTTPRequestHandler):
            def log_message(self, *a):
                pass

            def _send(self, code, body, ctype):
                try:
                    self.send_response(code)
                    self.send_header("Content-Type", ctype)
                    self.send_header("Content-Length", str(len(body)))
                    self.end_headers()
                    self.wfile.write(body)
                except Exception:
                    pass

            def _logo(self, slug):
                data = _LOGO_CACHE.get(slug)
                if data is None:
                    b64 = _LOGOS.get(slug)
                    if not b64:
                        return self._send(404, b"no logo", "text/plain")
                    import base64 as _b64
                    data = _b64.b64decode(b64)
                    _LOGO_CACHE[slug] = data
                try:
                    self.send_response(200)
                    self.send_header("Content-Type", "image/jpeg")
                    self.send_header("Content-Length", str(len(data)))
                    self.send_header("Cache-Control", "public, max-age=86400")
                    self.end_headers()
                    self.wfile.write(data)
                except Exception:
                    pass

            def do_GET(self):
                try:
                    self._route()
                except Exception as e:
                    _diag("rqerr", "%s %s" % (self.path[:40], str(e)[:50]))
                    try:
                        self._send(502, str(e)[:150].encode("utf-8"), "text/plain")
                    except Exception:
                        pass

            def _route(self):
                path = urllib.parse.urlparse(self.path).path
                parts = [p for p in path.split("/") if p]
                if len(parts) >= 2 and parts[0] == "logo":
                    return self._logo(parts[1])
                if parts and parts[0] == "seg":
                    return self._seg()
                if len(parts) >= 2 and parts[0] == "jce":
                    slug = parts[1]
                    ch = DEFAULT_CHANNELS[[c[0] for c in DEFAULT_CHANNELS].index(slug)]
                    body = _jce_live_playlist(ch)
                    _diag("rq", "jce %s 200" % slug)
                    return self._send(200, body.encode("utf-8"), "application/vnd.apple.mpegurl")
                if len(parts) >= 2 and parts[0] == "bk":
                    slug = parts[1]
                    idx = int(parts[2]) if len(parts) > 2 else 0
                    ch = DEFAULT_CHANNELS[[c[0] for c in DEFAULT_CHANNELS].index(slug)]
                    _bf = _BK_FAIL.get((slug, idx))
                    if _bf and time.time() - _bf < 20:
                        raise RuntimeError("bk playlist: cooling (recent 403)")
                    last = None
                    for fresh in (False, True):
                        for u in _bk_resolve(ch, fresh=fresh):
                            try:
                                text, _final = _fetch_playlist_pooled(u)
                                _tok = "bk_%s_%d" % (slug, idx)
                                _SEG_Q[_tok] = urllib.parse.urlsplit(u).query
                                _SEG_PL[_tok] = _final
                                _first = next((l.strip() for l in text.splitlines()
                                               if l.strip() and not l.startswith("#")), "")
                                _diag("segq", "%s %s" % ("1" if "?" in _first else "0",
                                      urllib.parse.urlparse(_first).hostname or "?"))
                                _diag("rq", "bk %s 200" % slug)
                                _prefetch_last(text)
                                return self._send(200, _rewrite_seg_http(text, _tok).encode("utf-8"),
                                                  "application/vnd.apple.mpegurl")
                            except Exception as e:
                                last = e
                    if last and "403" in str(last):
                        _BK_FAIL[(slug, idx)] = time.time()
                    raise RuntimeError("bk playlist: %s" % str(last)[:60])
                if len(parts) >= 2 and parts[0] == "dev":
                    slug = parts[1]
                    ent = _get_engine().resolve_entry(slug, LIVE_IDS[slug])
                    client = HttpClient(10.0, False)
                    resp = client.get(ent.final_url, dict(ent.playback_headers))
                    if not (200 <= resp.status < 300):
                        raise RuntimeError("dev playlist HTTP %s" % resp.status)
                    text = _absolutize(resp.text(), ent.final_url)
                    token = "d%d" % int(time.time())
                    _SEG_TOKENS[token] = dict(ent.playback_headers)
                    _diag("rq", "dev %s 200" % slug)
                    return self._send(200, _rewrite_seg_http(text, token).encode("utf-8"),
                                      "application/vnd.apple.mpegurl")
                if len(parts) >= 4 and parts[0] == "ts":
                    slug, start, end = parts[1], int(parts[2]), int(parts[3])
                    ch = DEFAULT_CHANNELS[[c[0] for c in DEFAULT_CHANNELS].index(slug)]
                    key = (slug, str(start), str(end))
                    with _TS_LOCK:
                        hit = _TS_CACHE.get(key)
                        if hit and time.time() - hit[1] < 900:
                            url = hit[0]
                        elif time.time() < _TS_RL_UNTIL[0] and hit:
                            url = hit[0]
                        elif time.time() < _TS_RL_UNTIL[0]:
                            raise RuntimeError("回看被限流，冷却中")
                        else:
                            try:
                                url = jce_timeshift_url(ch[3], ch[2], start, end, ch[4] or "fhd")
                            except Exception as je:
                                if "频繁" in str(je):
                                    _TS_RL_UNTIL[0] = time.time() + 90
                                    if hit:
                                        url = hit[0]
                                    else:
                                        raise
                                else:
                                    raise
                            _TS_CACHE[key] = (url, time.time())
                    _SEG_Q["ts"] = urllib.parse.urlsplit(url).query
                    try:
                        text = fetch_abs_playlist(url)
                        _segs = [l.strip() for l in text.splitlines() if l.strip() and not l.startswith("#")]
                        _tags = "".join(c for c, t in (("K", "#EXT-X-KEY:"), ("M", "#EXT-X-MAP:"),
                                                       ("B", "#EXT-X-BYTERANGE:"), ("G", "#EXT-X-GAP")) if t in text)
                        _diag("tsinfo", "%s segs=%d q=%s tags=%s" % (slug, len(_segs),
                              "1" if (_segs and "?" in _segs[0]) else "0", _tags or "-"))
                    except Exception:
                        good = _TS_PL_CACHE.get(key)
                        if good and time.time() - good[1] < 1800:
                            _diag("rq", "ts %s cached" % slug)
                            return self._send(200, _rewrite_seg_http(good[0], "ts").encode("utf-8"),
                                              "application/vnd.apple.mpegurl")
                        raise
                    _TS_PL_CACHE[key] = (text, time.time())
                    _diag("rq", "ts %s 200" % slug)
                    return self._send(200, _rewrite_seg_http(text, "ts").encode("utf-8"),
                                      "application/vnd.apple.mpegurl")
                return self._send(404, b"Not Found", "text/plain")

            def _seg_ts(self, url):
                # Mirror the original server's replay-segment fetch: only the
                # player's Range header is forwarded, nothing else.
                headers = {}
                rng = self.headers.get("Range")
                if rng:
                    headers["Range"] = rng
                t0 = time.time()
                sent = 0
                req = urllib.request.Request(url, headers=headers)
                try:
                    with _open_req(req, 15) as r:
                        code = r.status
                        self.send_response(code)
                        self.send_header("Content-Type",
                                         r.headers.get("Content-Type") or "video/MP2T")
                        for hname in ("Content-Length", "Content-Range", "Accept-Ranges"):
                            hv = r.headers.get(hname)
                            if hv:
                                self.send_header(hname, hv)
                        self.end_headers()
                        try:
                            while True:
                                chunk = r.read(65536)
                                if not chunk:
                                    break
                                self.wfile.write(chunk)
                                sent += len(chunk)
                        except (BrokenPipeError, ConnectionResetError):
                            _diag("tsseg", "abort %dB %dms" % (sent, int((time.time() - t0) * 1000)))
                            return
                    _diag("tsseg", "%s %dB %dms" % (code, sent, int((time.time() - t0) * 1000)))
                except Exception as e:
                    _diag("tsseg-err", "%s %dms" % (str(e)[:45], int((time.time() - t0) * 1000)))
                    raise

            def _seg_bk(self, url, tok):
                # Segments go over the SAME pooled connection as the playlist
                # fetch. On a 403, rebind: drop the connection, re-fetch the
                # media playlist on a fresh connection, then fetch the segment
                # on that same connection.
                _sf = _SEG_FAIL.get(url)
                if _sf and time.time() - _sf < 20:
                    raise RuntimeError("bk seg: cached 403 (cooling)")
                hit = _SEG_CACHE.get(url)
                if hit and time.time() - hit[2] < 90:
                    try:
                        return self._send(200, hit[0], hit[1])
                    except (BrokenPipeError, ConnectionResetError):
                        return
                host = urllib.parse.urlparse(url).hostname or ""
                last = None
                status = 0
                try:
                    status, hdrs, body, _f = _pool_fetch(url, {"Range": "bytes=0-"})
                    if status in (200, 206) and body:
                        ctype = hdrs.get("content-type") or "video/MP2T"
                        _seg_cache_put(url, body, ctype)
                        _diag("rq", "seg %s 200" % host)
                        try:
                            return self._send(200, body, ctype)
                        except (BrokenPipeError, ConnectionResetError):
                            return
                    last = RuntimeError("HTTP %s" % status)
                except Exception as e:
                    last = e
                if status == 403 or "403" in str(last):
                    pl = _SEG_PL.get(tok)
                    if pl:
                        try:
                            _pool_drop(urllib.parse.urlparse(pl).hostname or "")
                            _pool_fetch(pl, _PL_HEADERS)
                            status, hdrs, body, _f = _pool_fetch(url, {"Range": "bytes=0-"})
                            if status in (200, 206) and body:
                                ctype = hdrs.get("content-type") or "video/MP2T"
                                _seg_cache_put(url, body, ctype)
                                _diag("segfix", "rebind ok")
                                _diag("rq", "seg %s 200" % host)
                                try:
                                    return self._send(200, body, ctype)
                                except (BrokenPipeError, ConnectionResetError):
                                    return
                            last = RuntimeError("HTTP %s after rebind" % status)
                        except Exception as e:
                            last = e
                if last and "403" in str(last):
                    _SEG_FAIL[url] = time.time()
                raise RuntimeError("bk seg: %s" % str(last)[:60])

            def _seg(self):
                q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                url = (q.get("u") or [""])[0]
                tok = (q.get("t") or [""])[0]
                if not url.startswith("http"):
                    return self._send(404, b"bad url", "text/plain")
                if tok == "ts":
                    return self._seg_ts(url)
                if (tok.startswith("bk_") or tok == "bk") and tok not in _SEG_TOKENS:
                    return self._seg_bk(url, tok)
                appended = False
                if tok.startswith("bk") and "?" not in url and not (urllib.parse.urlparse(url).hostname or "").startswith("hlsliveali-"):
                    _q = _SEG_Q.get(tok)
                    if _q:
                        url = url + "?" + _q
                        appended = True
                        _diag("segfix", "query appended")
                headers = dict(PLAY_HEADERS)
                headers.update(_SEG_TOKENS.get(tok, {}))
                headers["Accept"] = "*/*"
                headers["Accept-Encoding"] = "identity"
                rng = self.headers.get("Range")
                if rng:
                    headers["Range"] = rng
                r = None
                for _try in range(2):
                    req = urllib.request.Request(url, headers=headers)
                    try:
                        r = _open_req(req, 20)
                        break
                    except urllib.error.HTTPError as he:
                        if he.code == 403 and not appended and "?" not in url and _SEG_Q.get(tok):
                            url = url + "?" + _SEG_Q[tok]
                            appended = True
                            _diag("segfix", "retry with query")
                            continue
                        raise
                with r:
                    code = r.status
                    ctype = r.headers.get("Content-Type") or "video/MP2T"
                    crange = r.headers.get("Content-Range")
                    self.send_response(code)
                    self.send_header("Content-Type", ctype)
                    if crange:
                        self.send_header("Content-Range", crange)
                    self.end_headers()
                    try:
                        while True:
                            chunk = r.read(65536)
                            if not chunk:
                                break
                            self.wfile.write(chunk)
                    except (BrokenPipeError, ConnectionResetError):
                        _diag("rq", "seg abort")
                        return
                _diag("rq", "seg %s %s" % (urllib.parse.urlparse(url).hostname, code))

        srv = _hs.ThreadingHTTPServer(("127.0.0.1", 0), _H)
        _SRV["port"] = srv.server_address[1]
        th = threading.Thread(target=srv.serve_forever, daemon=True)
        th.start()
        _diag("srv", "127.0.0.1:%d" % _SRV["port"])
        return _SRV["port"]
    except Exception as e:
        _SRV["err"] = str(e)[:80]
        _diag("srv-err", _SRV["err"])
        return None


def _relay(path):
    p = _start_server()
    if not p:
        return None
    return "http://127.0.0.1:%d%s" % (p, path)


class Spider(_BaseSpider):

    def getName(self):
        return "央卫直播"

    def getDependence(self):
        return []

    def action(self, action):
        return {}

    def destroy(self):
        return None

    def init(self, extend=""):
        self._by_slug = {c[0]: c for c in DEFAULT_CHANNELS}
        _start_server()

    # ---------------- 内部 ----------------

    def _vod(self, ch):
        return {
            "vod_id": ch[0],
            "vod_name": ch[1],
            "vod_pic": _logo_url(ch),
            "vod_remarks": _group_of(ch[0]),
        }

    def _catchup_episodes(self, ch):
        slug = ch[0]
        if slug not in TIMESHIFT_SUPPORTED and slug not in ("cctvfyjc", "cctvdyjc", "cctvhjjc"):
            return []
        now = int(time.time())
        lt = time.localtime(now)
        today0 = now - (lt.tm_hour * 3600 + lt.tm_min * 60 + lt.tm_sec)
        eps = []
        for day_back in (0, 1):
            day0 = today0 - day_back * 86400
            for h in range(22, 5, -2):
                start = day0 + h * 3600
                end = min(start + 7200, now)
                if end - start < 900:
                    continue
                label = "%s~%s" % (
                    time.strftime("%m-%d %H:%M", time.localtime(start)),
                    time.strftime("%H:%M", time.localtime(end)),
                )
                eps.append("%s$ts:%s:%d:%d" % (label, slug, start, end))
        return eps

    # ---------------- 六大接口 ----------------

    def homeContent(self, filter=False):
        groups = []
        for ch in DEFAULT_CHANNELS:
            g = _group_of(ch[0])
            if g not in groups:
                groups.append(g)
        return {"class": [{"type_id": g, "type_name": g} for g in groups], "filters": {}}

    def homeVideoContent(self):
        return {"list": [self._vod(ch) for ch in DEFAULT_CHANNELS]}

    def categoryContent(self, tid, pg="1", filter=None, extend=None):
        lst = [self._vod(ch) for ch in DEFAULT_CHANNELS if tid in ("", "全部") or _group_of(ch[0]) == tid]
        return {"list": lst, "page": 1, "pagecount": 1, "limit": max(len(lst), 1), "total": len(lst)}

    def detailContent(self, ids):
        if isinstance(ids, (list, tuple)):
            id_list = [str(x) for x in ids]
        else:
            id_list = [str(ids or "")]
        result = []
        for vid in id_list:
            ch = self._by_slug.get(vid)
            if not ch:
                continue
            slug = ch[0]
            vod = self._vod(ch)
            vod["vod_content"] = "%s · 央视频直播（本地取址：高码率/BK/JCE）" % ch[1]
            froms, urls = [], []
            if slug in BACKEND_CHANNELS:
                froms.append("高码率")
                urls.append("直播$dev:" + slug)
            eps = []
            try:
                bk = _bk_resolve(ch)
                eps.extend("线路%d$bk0:%s:%d" % (i + 1, slug, i) for i in range(len(bk)))
            except Exception as e:
                _diag("bk-detail", e)
                eps.append("线路1$bk0:%s:0" % slug)
            if slug not in _FORCE_BK:
                # JCE live demoted to last resort (v11.2): on the user's
                # device its playlists load but segments never sustain,
                # while BK lines play; keep JCE reachable as the last line.
                eps.append("线路%d$jce:%s" % (len(eps) + 1, slug))
            froms.append("直播")
            urls.append("#".join(eps))
            if _DIAG:
                vod["vod_content"] += "｜诊断：" + "；".join(_DIAG)
            vod["vod_play_from"] = "$$$".join(froms)
            vod["vod_play_url"] = "$$$".join(urls)
            result.append(vod)
        return {"list": result}

    def playerContent(self, flag, id, vipFlags=None):
        pid = str(id)
        try:
            if pid.startswith("jce:"):
                slug = pid[4:]
                _diag("pc-in", "jce " + slug)
                r = _relay("/jce/" + slug)
                if r:
                    _diag("ok", "jce relay " + r)
                    return {"parse": 0, "jx": 0, "playUrl": "", "url": r, "header": {}}
                ch = self._by_slug.get(slug)
                try:
                    u = _jce_live_url(ch)
                    return {"parse": 0, "jx": 0, "playUrl": "", "url": u, "header": {}}
                except Exception as e:
                    _diag("err", "jce " + str(e)[:80])
                    pid = "bk0:%s:0" % slug
            if pid.startswith("dev:"):
                slug = pid[4:]
                _diag("pc-in", "dev " + slug)
                r = _relay("/dev/" + slug)
                if r:
                    _diag("ok", "dev relay " + r)
                    return {"parse": 0, "jx": 0, "playUrl": "", "url": r, "header": {}}
                try:
                    ent = _get_engine().resolve_entry(slug, LIVE_IDS[slug])
                    _diag("ok", "dev " + ent.final_url[:70])
                    return {"parse": 0, "jx": 0, "playUrl": "", "url": ent.final_url,
                            "header": dict(ent.playback_headers)}
                except Exception as e:
                    _diag("err", "dev " + str(e)[:80])
                    pid = "bk0:%s:0" % slug
            if pid.startswith("ts:"):
                _diag("pc", "ts tap")
                parts = pid.split(":")
                slug = parts[1]
                _diag("pc-in", "ts " + slug)
                ch = self._by_slug.get(slug)
                r = _relay("/ts/%s/%s/%s" % (slug, parts[2], parts[3]))
                if r:
                    _diag("ok", "ts relay " + r)
                    return {"parse": 0, "jx": 0, "playUrl": "", "url": r, "header": {}}
                key = (slug, parts[2], parts[3])
                hit = _TS_CACHE.get(key)
                if hit and time.time() - hit[1] < 900:
                    url = hit[0]
                else:
                    url = jce_timeshift_url(ch[3], ch[2], int(parts[2]), int(parts[3]), ch[4] or "fhd")
                    _TS_CACHE[key] = (url, time.time())
                _diag("ok", "ts " + url[:70])
                return {"parse": 0, "jx": 0, "playUrl": "", "url": url, "header": dict(PLAY_HEADERS)}
            if pid.startswith("bk"):
                mode, slug, idx = pid[2], pid[4:].rsplit(":", 1)[0], int(pid.rsplit(":", 1)[1])
                _diag("pc-in", "bk%s %s" % (mode, slug))
                ch = self._by_slug.get(slug)
                r = _relay("/bk/%s/%d" % (slug, idx))
                if r:
                    _diag("ok", "bk relay " + r)
                    return {"parse": 0, "jx": 0, "playUrl": "", "url": r, "header": {}}
                urls = _bk_resolve(ch)
                u = urls[idx] if 0 <= idx < len(urls) else urls[0]
                if mode == "1":
                    u = u.replace("http://", "https://", 1)
                elif mode == "2":
                    u = _media_url(u)
                _diag("ok", "bk%s %s" % (mode, u[:70]))
                return {"parse": 0, "jx": 0, "playUrl": "", "url": u, "header": dict(PLAY_HEADERS)}
            if pid.startswith("http"):
                return {"parse": 0, "jx": 0, "playUrl": "", "url": pid, "header": dict(PLAY_HEADERS)}
            ch = self._by_slug.get(pid)
            if ch:
                urls = _bk_resolve(ch)
                return {"parse": 0, "jx": 0, "playUrl": "", "url": urls[0], "header": dict(PLAY_HEADERS)}
        except Exception as e:
            _diag("err", "pc " + str(e)[:90])
        return {"parse": 0, "jx": 0, "playUrl": "", "url": "", "header": {}}

    def searchContent(self, key, quick=False, pg="1"):
        key = (key or "").strip().lower()
        lst = [self._vod(ch) for ch in DEFAULT_CHANNELS if key in ch[1].lower() or key in ch[0].lower()]
        return {"list": lst, "page": 1, "pagecount": 1, "limit": max(len(lst), 1), "total": len(lst)}

    def isVideoFormat(self, url):
        return url is not None and ".m3u8" in str(url)

    def manualVideoCheck(self):
        return False

    # ---------------- 本地代理（播放器取清单/分片都走这里） ----------------

    def localProxy(self, param):
        _diag("proxy-in", "%s %s" % (type(param).__name__, str(param)[:90]))
        try:
            p = _proxy_params(param)
            do = p.get("do", "")
            if do == "pl":
                return self._proxy_playlist(p)
            if do == "seg":
                return self._proxy_segment(p)
        except Exception as e:
            _diag("proxy", e)
            return [502, "text/plain", str(e)[:200].encode("utf-8"), {}]
        _diag("proxy-miss", str(p)[:90])
        return [404, "text/plain", b"Not Found", {}]

    def _proxy_playlist(self, p):
        kind = p.get("kind", "")
        if kind == "bk":
            ch = self._by_slug.get(p.get("slug", ""))
            if not ch:
                return [404, "text/plain", b"no channel", {}]
            urls = _bk_resolve(ch)
            idx = int(p.get("idx", "0"))
            idx = idx if 0 <= idx < len(urls) else 0
            text = fetch_abs_playlist(urls[idx])
            _diag("pl-ok", "bk seg=%d" % len([l for l in text.splitlines() if l and not l.startswith("#")]))
            return [200, "application/vnd.apple.mpegurl",
                    _upgrade_https(text).encode("utf-8"), {}]
        if kind == "ts":
            ch = self._by_slug.get(p.get("slug", ""))
            if not ch:
                return [404, "text/plain", b"no channel", {}]
            url = jce_timeshift_url(ch[3], ch[2], int(p["start"]), int(p["end"]), ch[4] or "fhd")
            text = fetch_abs_playlist(url)
            _diag("pl-ok", "ts seg=%d" % len([l for l in text.splitlines() if l and not l.startswith("#")]))
            return [200, "application/vnd.apple.mpegurl",
                    _upgrade_https(text).encode("utf-8"), {}]
        if kind == "dev":
            slug = p.get("slug", "")
            ent = _get_engine().resolve_entry(slug, LIVE_IDS[slug])
            client = HttpClient(10.0, False)
            resp = client.get(ent.final_url, dict(ent.playback_headers))
            if not (200 <= resp.status < 300):
                raise RuntimeError("dev playlist HTTP %s" % resp.status)
            text = _absolutize(resp.text(), ent.final_url)
            token = str(abs(hash(ent.final_url)) % 100000000)
            _SEG_TOKENS[token] = dict(ent.playback_headers)
            text = _rewrite_seg_proxy(text, token)
            return [200, "application/vnd.apple.mpegurl", text.encode("utf-8"), {}]
        return [404, "text/plain", b"bad kind", {}]

    def _proxy_segment(self, p):
        url = urllib.parse.unquote(p.get("u", ""))
        if not url.startswith("http"):
            return [404, "text/plain", b"bad url", {}]
        headers = dict(_SEG_TOKENS.get(p.get("t", ""), {}))
        req = urllib.request.Request(url, headers=headers)
        with _open_req(req, 20) as r:
            data = r.read()
            ctype = r.headers.get("Content-Type") or "video/MP2T"
        return [200, ctype, data, {}]
